(async () => {
  const store = await import('/src/studio/store.ts');
  const ws = await import('/src/studio/documentWorkspaces.ts');
  const domain = await import('/src/studio/domain.ts');
  const revision = { id: 'doc-ground-floor', name: 'Ground floor plan rev C.pdf', kind: 'pdf', importedAt: new Date().toISOString(), pageCount: 3, sha256: 'c0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeeabcd', source: 'web' };
  const before = store.useStudio.getState().job;
  const opened = ws.restoreDocumentWorkspace({ ...before, documents: [...before.documents, revision] }, revision);
  // A locked manual calibration on sheet 0, the state a user reaches by grading a scale on the source.
  const calibration = { ...opened.calibrations[0], metresPerUnit: 0.0125, source: 'manual', confidence: 1, locked: true, knownDistanceM: 5, points: [{ x: 0, y: 0 }, { x: 400, y: 0 }] };
  const job = domain.fencingJobSchema.parse({ ...opened, calibrations: [calibration, ...opened.calibrations.slice(1)] });
  store.useStudio.setState({ pane: 'cost', job });
  return 'seeded ' + revision.name + ' activeDocumentId=' + job.activeDocumentId + ' sha=' + job.documents[job.documents.length - 1].sha256.slice(0, 8);
})()

const byLabel = (text) => [...document.querySelectorAll('label')].find(l => l.textContent.trim().startsWith(text));
const setValue = (el, value) => {
  const proto = el.tagName === 'SELECT' ? HTMLSelectElement.prototype : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, value);
  el.dispatchEvent(new Event('input', { bubbles: true }));
  el.dispatchEvent(new Event('change', { bubbles: true }));
};
const fill = (text, value) => { const el = byLabel(text)?.querySelector('input,select'); if (!el) throw Error('No field labelled: ' + text); setValue(el, value); return true; };
const click = (text) => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === text); if (!b) throw Error('No button: ' + text); if (b.disabled) throw Error('Button disabled: ' + text); b.click(); return true; };
const openWorkbench = () => { const w = document.querySelector('.industry-workbench'); if (!w) throw Error('No industry workbench'); w.open = true; return true; };
