(() => {
  const key = Object.keys(localStorage).filter(k => k.startsWith('xray.industry-drafts.v1:'))[0];
  if (!key) throw Error('No industry draft library in this project');
  const form = JSON.parse(localStorage.getItem(key)).drafts.roofing.form;
  const b = form.binding;
  if (!b) throw Error('Roofing draft has no saved binding');
  const expect = { schema: 'xray.industry-source-binding/1', sourceRevisionId: 'doc-ground-floor', sha256: 'c0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeec0ffeeabcd', sourceName: 'Ground floor plan rev C.pdf', units: 'm', evidenceClass: 'traced', reference: 'North plane traced on plan sheet A-201' };
  for (const [field, value] of Object.entries(expect)) if (b[field] !== value) throw Error('Saved binding ' + field + ' is ' + b[field] + ', expected ' + value);
  if (b.calibrationId === null) throw Error('Saved binding recorded no calibration identity');
  if (b.locator.kind !== 'page' || b.locator.pageIndex !== 1) throw Error('Saved locator is ' + JSON.stringify(b.locator));
  if (b.projectId !== JSON.parse(localStorage.getItem(key)).projectId) throw Error('Binding project does not match the draft library project');
  return JSON.stringify(b);
})()

